CREATE VIEW current_render_manifests AS SELECT m.id,m.project_id,m.content_hash,m.status FROM render_manifests m WHERE EXISTS(SELECT 1 FROM projects p WHERE p.id=m.project_id AND p.archived_at IS NULL AND p.active_script_version_id=json_extract(m.manifest_json,'$.scriptVersionId') AND (SELECT json_array_length(script_json,'$.sections') FROM script_versions WHERE id=p.active_script_version_id AND status='APPROVED') = json_array_length(m.manifest_json,'$.scenes') AND NOT EXISTS(SELECT 1 FROM json_each(m.manifest_json,'$.scenes') r WHERE NOT EXISTS(SELECT 1 FROM scenes s JOIN scene_versions v ON v.id=s.active_version_id WHERE s.id=json_extract(r.value,'$.sceneId') AND s.project_id=p.id AND s.archived_at IS NULL AND v.status='APPROVED' AND v.id=json_extract(r.value,'$.sceneVersionId') AND v.hash=json_extract(r.value,'$.contentHash') AND EXISTS(SELECT 1 FROM script_versions sv,json_each(sv.script_json,'$.sections') section WHERE sv.id=p.active_script_version_id AND json_extract(section.value,'$.stableKey')=s.stable_key)))) GROUP BY m.id;
